import itertools
from z3 import *

# Let's try Z3 with a different encoding and strategy
n_golfers = 30
n_groups = 10
n_weeks = 8

# Use integer variables for group assignment
x = [[Int(f"x_{w}_{i}") for i in range(n_golfers)] for w in range(n_weeks)]

s = Solver()
s.set("timeout", 30000)  # 30 seconds

# Domain
for w in range(n_weeks):
    for i in range(n_golfers):
        s.add(x[w][i] >= 0, x[w][i] <= n_groups - 1)

# Each group has exactly 3 golfers per week
for w in range(n_weeks):
    for g in range(n_groups):
        # Count golfers in group g
        s.add(PbEq([(x[w][i] == g, 1) for i in range(n_golfers)], 3))

# No pair repeats
# For each pair (i,j), sum over weeks of (x[w][i] == x[w][j]) <= 1
for i in range(n_golfers):
    for j in range(i+1, n_golfers):
        s.add(PbLe([(x[w][i] == x[w][j], 1) for w in range(n_weeks)], 1))

print("Solving with Z3...")
result = s.check()
print("Result:", result)

if str(result) == "sat":
    m = s.model()
    solution = []
    for w in range(n_weeks):
        for i in range(n_golfers):
            solution.append(m.evaluate(x[w][i]).as_long())
    print("Solution:", solution)
    # Verify
    # Check group sizes
    for w in range(n_weeks):
        groups = [[] for _ in range(n_groups)]
        for i in range(n_golfers):
            g = solution[w*30 + i]
            groups[g].append(i)
        for g in range(n_groups):
            if len(groups[g]) != 3:
                print(f"ERROR: week {w}, group {g} has {len(groups[g])} golfers")
    # Check pair uniqueness
    pairs_seen = {}
    for w in range(n_weeks):
        for g in range(n_groups):
            members = [i for i in range(n_golfers) if solution[w*30 + i] == g]
            for a, b in itertools.combinations(members, 2):
                key = (min(a,b), max(a,b))
                if key in pairs_seen:
                    print(f"ERROR: pair {key} seen in weeks {pairs_seen[key]} and {w}")
                pairs_seen[key] = w
    print("Verification complete")
else:
    print("UNSAT or unknown")
